import { createBucket, put, removeBucket } from '@tigrisdata/storage';
import { S3Client, ListObjectsV2Command, DeleteObjectsCommand } from '@aws-sdk/client-s3';

const bucket = process.env.BUCKET;

const admin = new S3Client({
  endpoint: 'REDACTED',
  region: 'REDACTED',
  credentials: {
    accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID,
    secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY,
  },
  forcePathStyle: true,
});

// Idempotency: if the bucket already exists, wipe objects then drop it.
try {
  await admin.send(new ListObjectsV2Command({ Bucket: bucket }));
  let token;
  do {
    const res = await admin.send(new ListObjectsV2Command({ Bucket: bucket, ContinuationToken: token }));
    if (res.Contents && res.Contents.length > 0) {
      await admin.send(new DeleteObjectsCommand({
        Bucket: bucket,
        Delete: { Objects: res.Contents.map(o => ({ Key: o.Key })) },
      }));
    }
    token = res.IsTruncated ? res.NextContinuationToken : undefined;
  } while (token);
  await removeBucket(bucket, { force: true });
} catch (_) {
  // Bucket does not exist, that's fine.
}

const created = await createBucket(bucket, { enableSnapshot: true });
if (created.error) throw new Error('createBucket: ' + created.error.message);

await put('seed1.txt', 'seed-1', { bucket, access: 'private' });
await put('seed2.txt', 'seed-2', { bucket, access: 'private' });

console.log('setup complete for ' + bucket);
